                    lentiaDelta -= 5;
                }
            }

            if (d.round === 3) {
                if (d.greenBond === 'yes') {
                    if (ds.hasGHGReporting) {
                        govDelta += 60;
                        envDelta += 30;
                        ebitdaDelta += 0.30;
                        lentiaDelta += 5;
                    } else {
                        events = window.mySimulation.t('event_bond_rejected');
                        greenwashDelta -= 10;
                    }
                }

                if (d.scope3Disclosure === 'full') {
                    envDelta += 80;
                    socDelta += 20;
                    lentiaDelta += 15;
                    trustDelta += 10;
                } else if (d.scope3Disclosure === 'partial') {
                    envDelta += 40;
                    lentiaDelta += 8;
                    trustDelta += 3;
                } else {
