                var newEsg = this._calcESG(ds.envScore + envDelta, ds.socScore + socDelta, ds.govScore + govDelta);
                if (newEsg >= 600 && acquisitionRoll < 0.25) {
                    events += (events ? '<br>' : '') + window.mySimulation.t('event_acquisition_offer');
                }
            }

            ds.envScore = Math.min(1000, Math.max(0, ds.envScore + envDelta));
            ds.socScore = Math.min(1000, Math.max(0, ds.socScore + socDelta));
