        _calcESG(env, soc, gov) {
            return (env * 0.4) + (soc * 0.35) + (gov * 0.25);
        }

        _getESGRating(score) {
            if (score >= 800) return 'AAA';
            if (score >= 700) return 'AA';
            if (score >= 600) return 'BB';
            if (score >= 450) return 'B';
            if (score >= 300) return 'CCC';
            return 'CCC';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUND_BRIEFINGS.length - 1);

            var briefTitle = document.getElementById('briefingTitle');
            if (briefTitle) briefTitle.textContent = window.mySimulation.t(this.ROUND_BRIEFINGS[idx].titleKey);

            var briefText = document.getElementById('briefingText');
            if (briefText) briefText.textContent = window.mySimulation.t(this.ROUND_BRIEFINGS[idx].textKey);

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');

            var period = state.currentPeriod || 1;

            if (r1) r1.style.display = (period === 1) ? 'block' : 'none';
            if (r2) r2.style.display = (period === 2) ? 'block' : 'none';
            if (r3) r3.style.display = (period === 3) ? 'block' : 'none';

            if (period === 3) {
                var bondCtx = document.getElementById('bondContext');
                if (bondCtx) {
                    var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : null;
                    if (ds && ds.hasGHGReporting) {
                        bondCtx.textContent = window.mySimulation.t('bond_eligible');
                    } else {
                        bondCtx.textContent = window.mySimulation.t('bond_ineligible');
                    }
                }
            }

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';
        }

        _updateBudgetDisplay(state) {
            var budgetEl = document.getElementById('budgetInfo');
            if (!budgetEl) return;
            var ids = ['chkOrganic', 'chkWaterless', 'chkWage', 'chkBoard', 'chkGHG', 'chkISO'];
            var costs = [800, 1900, 310, 0, 80, 120];
            var total = 0;
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && el.checked) total += costs[i];
            }
            var remaining = 3200 - total;
            budgetEl.textContent = window.mySimulation.t('budget_remaining') + ' ' + remaining.toLocaleString() + 'M';
            budgetEl.style.color = remaining < 0 ? '#c62828' : '#1b5e20';

            var self = this;
            for (var j = 0; j < ids.length; j++) {
                var chk = document.getElementById(ids[j]);
                if (chk && !chk._budgetListener) {
                    chk._budgetListener = true;
                    chk.addEventListener('change', function() {
                        self._updateBudgetDisplay(state);
                    });
                }
            }
        }

        _updateESGBars(ds) {
            var envBar = document.getElementById('envBar');
            if (envBar) envBar.style.width = Math.min(100, (ds.envScore / 1000) * 100) + '%';
            var socBar = document.getElementById('socBar');
            if (socBar) socBar.style.width = Math.min(100, (ds.socScore / 1000) * 100) + '%';
            var govBar = document.getElementById('govBar');
            if (govBar) govBar.style.width = Math.min(100, (ds.govScore / 1000) * 100) + '%';
        }

        _showEvent(text) {
            var panel = document.getElementById('eventPanel');
            if (!panel || !text) return;
            var titleEl = document.getElementById('eventTitle');
            var textEl = document.getElementById('eventText');
            if (titleEl) titleEl.textContent = '⚠ Event';
            if (textEl) textEl.innerHTML = text;
            panel.style.display = 'block';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new BioTexAdapter(), {
            simulationType: 'biotex_esg_299',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
